import os
import re
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


@dataclass
class FieldResult:
    value: Any
    confidence: float


class StructuredDocumentExtractionError(ValueError):
    pass


def _get_env(name: str, required: bool = True) -> Optional[str]:
    value = os.getenv(name)
    if required and not value:
        raise StructuredDocumentExtractionError(f"Missing required environment variable: {name}")
    return value


def _confidence_from_field(field: Any) -> float:
    confidence = getattr(field, "confidence", None)
    if confidence is None:
        confidence = field.get("confidence") if isinstance(field, dict) else None
    if confidence is None:
        return 0.0
    try:
        return float(confidence)
    except Exception as exc:
        raise StructuredDocumentExtractionError(f"Invalid confidence value: {confidence!r}") from exc


def _field_value(field: Any) -> Any:
    value = getattr(field, "value", None)
    if value is None and isinstance(field, dict):
        value = field.get("value")
    if value is None:
        value = getattr(field, "content", None)
    if value is None and isinstance(field, dict):
        value = field.get("content")
    return value


def _normalize_field(field: Any) -> FieldResult:
    return FieldResult(value=_field_value(field), confidence=_confidence_from_field(field))


def _extract_document_fields(result: Any) -> Dict[str, FieldResult]:
    documents = getattr(result, "documents", None) or []
    if not documents:
        raise StructuredDocumentExtractionError("No structured documents were returned by the provider.")

    document = documents[0]
    fields = getattr(document, "fields", None) or {}
    normalized: Dict[str, FieldResult] = {}

    for key, field in fields.items():
        normalized[str(key)] = _normalize_field(field)

    return normalized


def _validate_required_fields(
    fields: Dict[str, FieldResult],
    required_fields: List[str],
    min_confidence: float,
) -> Dict[str, Any]:
    errors: List[str] = []
    validated: Dict[str, Any] = {}

    for name in required_fields:
        if name not in fields:
            errors.append(f"Missing required field: {name}")
            continue

        field = fields[name]
        if field.value in (None, "", []):
            errors.append(f"Empty required field: {name}")
            continue

        if field.confidence < min_confidence:
            errors.append(
                f"Low confidence for field '{name}': {field.confidence:.4f} < {min_confidence:.4f}"
            )
            continue

        validated[name] = {"value": field.value, "confidence": field.confidence}

    if errors:
        raise StructuredDocumentExtractionError("; ".join(errors))

    return validated


def extract_invoice_structured_fields(
    document_path: str,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.85,
) -> Dict[str, Any]:
    """
    Extract and validate required structured fields from an invoice document using
    Azure Document Intelligence prebuilt invoice.

    Environment variables:
        AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
        AZURE_DOCUMENT_INTELLIGENCE_KEY
    """
    endpoint = _get_env("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = _get_env("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if required_fields is None:
        required_fields = [
            "VendorName",
            "InvoiceDate",
            "InvoiceId",
            "DueDate",
            "SubTotal",
            "TotalTax",
            "InvoiceTotal",
        ]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
        )
        result = poller.result()

    fields = _extract_document_fields(result)
    validated_fields = _validate_required_fields(fields, required_fields, min_confidence)

    return {
        "provider": "azure-ai-documentintelligence",
        "model_id": "prebuilt-invoice",
        "validated_fields": validated_fields,
        "all_fields": {
            name: {"value": fr.value, "confidence": fr.confidence}
            for name, fr in fields.items()
        },
    }
